property.value:
//UserClass[@Nested = false()][
	ModifierNode[
		@WithoutSharing = false() and
		@WithSharing = false() and
		@InheritedSharing = false() and
		($reportInTestClasses or @Test = false())
	]
]

//UserClass[@Nested = true()]
	[not(ends-with(lower-case(@SuperClassName), 'exception'))]
	[not(ancestor::UserClass[ModifierNode[@Test = true()]])]
	[not(ancestor::UserClass[@SuperClassName != '' or string-join(@InterfaceNames, '') != ''])]
	[
		ModifierNode[
			@WithoutSharing = false() and
			@WithSharing = false() and
			@InheritedSharing = false()
		]
	]

/ApexFile/UserClass[
	ModifierNode[
		@Public = false() and
		@Private = false() and
		@Global = false()
	] and
	@Nested = false()
]

//IfElseBlockStatement[
	let $conditions := IfBlockStatement/StandardCondition/*,
		$ors := $conditions/descendant-or-self::BooleanExpression[@Op = '||'],
		$leaves := ($conditions | $ors/*)[not(self::BooleanExpression[@Op = '||'])],
		$method := ancestor::Method[1],
		$class := ancestor::UserClass[1],
		$fields := ($class/Field | $class/Property/Field),
		$declared := ($method//VariableDeclaration/lower-case(@Image), $method/Parameter/lower-case(@Image), $fields/lower-case(@Name)),
		$isValue := function($node) {
			exists($node/self::LiteralExpression[@LiteralType = ('STRING', 'INTEGER', 'LONG', 'NULL')]
				| $node/self::PrefixExpression[@Op = '-'][LiteralExpression[@LiteralType = ('INTEGER', 'LONG')]]
				| $node/self::VariableExpression[ReferenceExpression[@Image != ''][not(*)][not(lower-case(@Image) = $declared)]])
		},
		$name := function($node) {
			lower-case(string-join(($node/ReferenceExpression/@Image[. != ''], $node/@Image), '.'))
		},
		$subjects := function($leaf) {
			if ($leaf/self::InstanceOfExpression) then $leaf/VariableExpression ! $name(.)
			else for $operand in $leaf/VariableExpression return (if ($isValue($leaf/*[not(. is $operand)])) then $name($operand) else ())
		},
		$subject := (for $candidate in $subjects($leaves[1]) return $candidate[every $leaf in $leaves satisfies $candidate = $subjects($leaf)])[1],
		$type := lower-case((
			$method//VariableDeclaration[lower-case(@Image) = $subject]/@Type,
			$method/Parameter[lower-case(@Image) = $subject]/@Type,
			$fields[lower-case(@Name) = $subject]/@Type
		)[1])
	return exists($leaves)
		and (every $leaf in $leaves satisfies $leaf[self::BooleanExpression[@Op = '=='] or self::InstanceOfExpression])
		and exists($subject)
		and not($type = ('id', 'decimal', 'double', 'boolean', 'date', 'datetime', 'time', 'blob', 'object', 'sobjecttype', 'schema.sobjecttype'))
		and (not($leaves/self::InstanceOfExpression) or ($type = 'sobject' and empty($ors)))
		and count($leaves[not(*/@LiteralType = 'NULL')]) >= $minConditions
]

//FormalComment[
	let $c := @Image,
	    $d := if (contains($c, '@description')) then substring-after($c, '@description') else replace($c, '^\s*/\*+', ''),
	    $t := normalize-space(replace(replace(replace($d, '(^|[\s*])@(param|return|throws|exception|deprecated|since|see|author|version|group|example)(\s|$).*$', '', 'is'), '(^|\n)\s*\*+/?', ' ', 's'), '\*+/\s*$', ''))
	return string-length($t) < 10 and (contains($c, '@description') or string-length($t) > 0)
]

//Method[FormalComment][
	let $tags := for $part in tokenize(lower-case(FormalComment/@Image), '@throws\s+')[position() > 1]
		return tokenize(tokenize($part, '[^\w.]')[1], '\.')[last()]
	return some $throw in .//ThrowStatement satisfies (
		let $name := $throw/VariableExpression[not(*[not(self::EmptyReferenceExpression)])]/lower-case(@Image),
			$declared := (
				$throw/NewObjectExpression/@Type,
				$throw/ancestor::CatchBlockStatement[lower-case(@VariableName) = $name][1]/@ExceptionType,
				.//VariableDeclaration[lower-case(@Image) = $name]/@Type,
				Parameter[lower-case(@Image) = $name]/@Type
			)[1],
			$type := replace(lower-case(string($declared)), '^.*\.', '')
		return not($throw/ancestor::BlockStatement[parent::TryCatchFinallyBlockStatement][not(preceding-sibling::*)]
				/following-sibling::CatchBlockStatement[replace(lower-case(@ExceptionType), '^.*\.', '') = ('exception', $type)])
			and (if ($type = '') then empty($tags) else not($type = $tags))
	)
]

//*[ModifierNode/Annotation[lower-case(@Name) = 'deprecated']][not(self::Field or self::UserEnum or parent::Property)][
	let $c := string((FormalComment | FieldDeclaration/FormalComment)[1]/@Image),
	    $has := matches($c, '(^|[\s*])@deprecated(\s|$)', 'i'),
	    $after := replace($c, '^.*?(^|[\s*])@deprecated(\s|$)', '', 'is'),
	    $t := normalize-space(replace(replace(replace($after, '(^|[\s*])@(param|return|throws|exception|deprecated|since|see|author|version|group|example|description)(\s|$).*$', '', 'is'), '(^|\n)\s*\*+/?', ' ', 's'), '\*+/\s*$', ''))
	return not($has and string-length($t) > 0)
]

let $allowed := for $name in $allowedNames return lower-case($name)
return (
	//VariableDeclaration[string-length(@Image) = 1]
		[not(lower-case(@Image) = ('i', 'j') and parent::VariableDeclarationStatements/parent::ForLoopStatement)]
		[not(lower-case(@Image) = $allowed)]
	| //Field[@RealLoc = true()][not(parent::UserEnum)][string-length(@Name) = 1][not(lower-case(@Name) = $allowed)]
	| //Parameter[@RealLoc = true()][string-length(@Image) = 1][not(lower-case(@Image) = $allowed)]
	| //CatchBlockStatement[string-length(@VariableName) = 1][not(lower-case(@VariableName) = ('e', $allowed))]
)[$reportInTestClasses or not(ancestor::UserClass/ModifierNode[@Test = true()])]

//Method[@Arity = 0][@Constructor = false()][lower-case(@ReturnType) != 'void'][matches(@Image, '^get.', 'i')]
	[parent::UserClass[not(@InterfaceNames != '')]]
	[not(ModifierNode[@Override = true() or @Virtual = true() or @Abstract = true() or @Global = true()])]
	[not(ModifierNode/Annotation[not(lower-case(@Name) = ('testvisible', 'suppresswarnings'))])]
	[
		let $field := lower-case(substring(@Image, 4)),
			$static := ModifierNode/@Static
		return BlockStatement[count(*) = 1]/ReturnStatement/VariableExpression[EmptyReferenceExpression or ReferenceExpression/ThisVariableExpression][lower-case(@Image) = $field]
			and parent::UserClass/(Field | Property/Field)[lower-case(@Image) = $field][ModifierNode/@Static = $static]
	]

let $allowed := for $number in $allowedNumbers return number(normalize-space($number)),
	$value := function($node) {
		if ($node/self::PrefixExpression[@Op = '-']) then -number($node/LiteralExpression[@LiteralType = ('INTEGER', 'LONG', 'DECIMAL', 'DOUBLE')]/@Image)
		else number($node/self::LiteralExpression[@LiteralType = ('INTEGER', 'LONG', 'DECIMAL', 'DOUBLE')]/@Image)
	}
return //LiteralExpression[@LiteralType = ('INTEGER', 'LONG', 'DECIMAL', 'DOUBLE')]
	[not(ancestor::UserClass/ModifierNode[@Test = true()])]
	[not($value((parent::PrefixExpression[@Op = '-'], .)[1]) = $allowed)]
	[not(ancestor-or-self::*[parent::ArrayLoadExpression or parent::ArrayStoreExpression][preceding-sibling::*])]
	[not(ancestor::StandardCondition[parent::ForLoopStatement or parent::WhileLoopStatement or parent::DoLoopStatement])]
	[not(ancestor::FieldDeclarationStatements[ModifierNode[@Static = true() and @Final = true()]])]
	[not(ancestor::AssignmentExpression[ancestor::Method[1][@StaticInitializer = true()]]/*[1][self::VariableExpression[not(ReferenceExpression[@Image != ''])]]/lower-case(@Image)
		= ancestor::UserClass[1]/FieldDeclarationStatements[ModifierNode[@Static = true() and @Final = true()]]/FieldDeclaration/lower-case(@Name))]
	[not(ancestor::LiteralCase)]
	[not(
		let $operand := (parent::PrefixExpression[@Op = '-'], .)[1]
		return $operand/parent::BooleanExpression[@Op = ('==', '!=', '<>', '===', '!==', '<', '<=', '>', '>=')]
			and (some $other in $operand/../*[not(. is $operand)] satisfies $value($other) = $allowed)
	)]

//SoqlExpression[matches(replace(@Query, "'[^']*'", "''"), '\sWHERE\s(.*(!=|<>)|(.*[\s(])?NOT\s*[\s(]|.*\sEXCLUDES\s*\()', 'is') or matches(@Query, "\sLIKE\s*'[%_]", 'i')]
|
//LiteralExpression[@String = true()][matches(@Image, '^\s*SELECT\s.*\sFROM\s', 'is')][matches(replace(@Image, "'[^']*'", "''"), '\sWHERE\s(.*(!=|<>)|(.*[\s(])?NOT\s*[\s(]|.*\sEXCLUDES\s*\()', 'is') or matches(@Image, "\sLIKE\s*\\?'[%_]", 'i')]
